CREATE DATABASE IF NOT EXISTS logistics_fleet CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE logistics_fleet;
CREATE TABLE IF NOT EXISTS vehicles(id INT AUTO_INCREMENT PRIMARY KEY,vehicle_number VARCHAR(30) NOT NULL UNIQUE,vehicle_type VARCHAR(60) NOT NULL,capacity DECIMAL(8,2) NOT NULL,status ENUM('Available','On Trip','In Maintenance') NOT NULL DEFAULT 'Available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS drivers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(25) NOT NULL,license_number VARCHAR(50) NOT NULL UNIQUE,status ENUM('Available','On Trip','Unavailable') NOT NULL DEFAULT 'Available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trips(id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,driver_id INT NOT NULL,origin VARCHAR(120) NOT NULL,destination VARCHAR(120) NOT NULL,trip_date DATE NOT NULL,status ENUM('Scheduled','In Progress','Completed','Cancelled') NOT NULL DEFAULT 'Scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),FOREIGN KEY(driver_id) REFERENCES drivers(id));
CREATE TABLE IF NOT EXISTS maintenance(id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,service_type VARCHAR(120) NOT NULL,service_date DATE NOT NULL,cost DECIMAL(10,2) NOT NULL DEFAULT 0,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id));
